import os, json, subprocess, hashlib, urllib.request, datetime

ROOT = '/home/user/video-analytics'
TARGETS = ['rolling-cache-sink-a', 'rolling-cache-sink-b', 'media-worker']
def run(args, env=None):
    p = subprocess.run(args, cwd=ROOT, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True)
    return {'args': args, 'returncode': p.returncode, 'stdout': p.stdout, 'stderr': p.stderr}

out = {'utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'root': ROOT, 'files': {}, 'commands': {}, 'api': {}}
paths = [
    'scripts/midterm_start.sh', 'scripts/runtime/precreate_operator_dual_runtime.sh',
    'infra/docker-compose.midterm.yml', 'infra/midterm-storage.override.yml',
    'infra/operator-dual-runtime.override.yml', 'services/api/app/services/runtime_control.py',
    'services/api/app/services/runtime_topology.py', 'services/api/app/services/runtime_apply.py',
    'services/api/app/routers/runtime.py', 'infra/env/midterm.env',
]
for rel in paths:
    p = os.path.join(ROOT, rel)
    item = {'exists': os.path.exists(p), 'realpath': os.path.realpath(p)}
    if item['exists']:
        data = open(p, 'rb').read()
        item.update({'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)})
        if not rel.endswith('.env'):
            item['text'] = data.decode('utf-8')
    out['files'][rel] = item
inspect = run(['docker','container','inspect'] + ['video-analytics-midterm-' + x for x in TARGETS])
out['commands']['inspect'] = inspect
clean = {'PATH':'/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin', 'HOME':'/home/user', 'USER':'user', 'LANG':'C', 'TZ':'Asia/Seoul'}
base = ['docker','compose','--project-directory',ROOT,'--env-file',ROOT+'/infra/env/midterm.env','-f',ROOT+'/infra/docker-compose.midterm.yml']
variants = {
    'base_clean': [],
    'storage_operator_clean': ['-f',ROOT+'/infra/midterm-storage.override.yml','-f',ROOT+'/infra/operator-dual-runtime.override.yml'],
}
for name, extra in variants.items():
    result = run(base + extra + ['--profile','operator-dual-runtime','config','--format','json'], clean)
    if result['returncode'] == 0:
        config = json.loads(result.pop('stdout'))
        result['project_name'] = config.get('name')
        result['services'] = {k: config['services'][k] for k in TARGETS}
        result['all_services'] = sorted(config.get('services', {}))
    out['commands'][name] = result
out['commands']['compose_version'] = run(['docker','compose','version'])
out['commands']['ambient_key_names'] = {'keys': sorted(k for k in os.environ if k.startswith(('ROLLING_CACHE','PRESSURE_','MEDIA_WORKER')))}
for suffix in ['control', 'topology-config', 'topology-config/apply-status', 'performance-config', 'overview']:
    url = 'http://127.0.0.1:8090/api/v1/runtime/' + suffix
    try:
        with urllib.request.urlopen(url, timeout=30) as r:
            out['api'][suffix] = {'url':url,'status':r.status,'data':json.load(r)}
    except Exception as e:
        out['api'][suffix] = {'url':url,'error':repr(e)}
print(json.dumps(out, ensure_ascii=False))
